import{_ as t,o as c,c as a,a3 as h}from"./chunks/framework.DX_KL3e0.js";const d=JSON.parse('{"title":"Quản lý (Manager)","description":"","frontmatter":{},"headers":[],"relativePath":"vai-tro/quan-ly.md","filePath":"vai-tro/quan-ly.md","lastUpdated":1781595364000}'),g={name:"vai-tro/quan-ly.md"};function o(i,n,e,r,u,l){return c(),a("div",null,[...n[0]||(n[0]=[h('<h1 id="quan-ly-manager" tabindex="-1">Quản lý (Manager) <a class="header-anchor" href="#quan-ly-manager" aria-label="Permalink to &quot;Quản lý (Manager)&quot;">​</a></h1><p>Trang <strong>lối đi nhanh</strong> cho vai trò <strong>Quản lý</strong> (<code>manager</code>) — phụ trách một phòng/đội. Ngoài các quyền tự phục vụ như người dùng thường, Quản lý còn <strong>xét duyệt</strong> cho cấp dưới và <strong>đặt yêu cầu tuyển dụng</strong>.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Mã vai trò:</strong> <code>manager</code>.</li><li><strong>Phạm vi dữ liệu:</strong> theo <strong>công ty được gán</strong> (giống Admin).</li><li><strong>Quyền mặc định:</strong> như Admin nhưng <strong>Người dùng / Tổ chức / Cài đặt</strong> chỉ <code>Xem</code>; không có quyền <code>Xóa</code>.</li></ul></div><h2 id="ban-thay-nhung-gi" tabindex="-1">Bạn thấy những gì? <a class="header-anchor" href="#ban-thay-nhung-gi" aria-label="Permalink to &quot;Bạn thấy những gì?&quot;">​</a></h2><p>Quản lý nhìn thấy phần lớn module nghiệp vụ (Bảng điều khiển, Tài sản, Công việc, Ticket, Tổ chức, Lịch sử...), cộng các module luôn mở (<strong>Tra Cứu</strong>, <strong>Chấm công</strong>, <strong>Hồ sơ của tôi</strong>). Hai điểm đặc trưng của vai trò này:</p><ul><li><strong>Duyệt yêu cầu</strong> (<code>/duyet-yeu-cau</code>): Quản lý luôn xét duyệt được <strong>Bù công</strong> và <strong>Tăng ca</strong> của cấp dưới. Nút <strong>Duyệt bảng công</strong> chỉ hiện khi được cấp quyền <code>Xác nhận bảng công</code> (attendance.approve).</li><li><strong>Yêu cầu tuyển dụng</strong> (<code>/recruitment-order</code>): cổng đặt yêu cầu tuyển dụng cho phòng ban — Quản lý mặc định thấy.</li></ul><h2 id="cong-viec-thuong-ngay" tabindex="-1">Công việc thường ngày <a class="header-anchor" href="#cong-viec-thuong-ngay" aria-label="Permalink to &quot;Công việc thường ngày&quot;">​</a></h2><ul><li>[ ] Duyệt <strong>bù công</strong> và <strong>tăng ca</strong> của nhân viên trong đội → <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu</a></li><li>[ ] Xác nhận <strong>bảng công</strong> đội ngũ (nếu được cấp quyền) → <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu</a></li><li>[ ] Theo dõi bảng công, chấm công của phòng → <a href="/help/chuc-nang/cham-cong.html">Chấm công &amp; Nghỉ phép</a></li><li>[ ] Đặt <strong>yêu cầu tuyển dụng</strong> mới cho phòng ban → <a href="/help/chuc-nang/nguon-nhan-luc.html">Nguồn nhân lực (ATS)</a></li><li>[ ] Theo dõi công việc &amp; ticket của đội → <a href="/help/chuc-nang/cong-viec.html">Công việc</a> · <a href="/help/chuc-nang/tickets.html">Ticket Hỗ trợ</a></li><li>[ ] Xem bảng điều khiển tổng quan → <a href="/help/chuc-nang/dashboard.html">Dashboard</a></li><li>[ ] Tự phục vụ: chấm công, hồ sơ, đặt phòng → <a href="/help/chuc-nang/ho-so-cua-toi.html">Hồ sơ của tôi</a> · <a href="/help/chuc-nang/dat-phong.html">Đặt phòng họp</a></li></ul><div class="info custom-block"><p class="custom-block-title">📸 Ảnh minh họa</p><p>Màn hình duyệt yêu cầu cấp dưới của vai trò Quản lý. <em>(Ảnh sẽ được bổ sung.)</em></p></div><div class="warning custom-block"><p class="custom-block-title">Lưu ý</p><p>Quản lý <strong>chỉ xem</strong> với Người dùng, Tổ chức và Cài đặt hệ thống; không tự tạo/sửa người dùng hay cơ cấu tổ chức. Việc đó thuộc Admin/Super Admin.</p></div><hr><p><em>Liên quan:</em> <a href="/help/bat-dau/phan-quyen.html">Phân quyền &amp; vai trò</a> · <a href="/help/quan-tri/cau-hinh-cham-cong.html">Cấu hình Chấm công</a></p>',12)])])}const m=t(g,[["render",o]]);export{d as __pageData,m as default};
